#include "stdafx.h"#include "H_Class.h"#include <_alarmentry.h>#include <ConnectH.h>static SBlockCreate DIGACQ( "DIGACQ", SH_DIGACQ::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_DIGACQ,W_DIGACQ,55)void SH_DIGACQ::InitParm(){#include "Blocks/DIGACQ.h" s_defFlag = SVarInfo::efParam;#include "Blocks/DIGACQ_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class DIGACQ_IMPL : public W_DIGACQ{public:  void StepT( SStepCalcParams &dt, LPCSTR pFullName );  void StepAfterRestoreState();};void SH_DIGACQ::StepAfterRestoreState(){  DIGACQ_IMPL *impl = reinterpret_cast<DIGACQ_IMPL*>(W);  impl->StepAfterRestoreState();}void SH_DIGACQ::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  DIGACQ_IMPL *impl = reinterpret_cast<DIGACQ_IMPL*>(W);  impl->StepT( dt, BlockName );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void DIGACQ_IMPL::StepAfterRestoreState(){  if( !PVFL )  {    if( _NORMAL::State0==NORMAL.V )      OFFNRMALM.FL = false;    else if( _NORMAL::State1==NORMAL.V )      OFFNRMALM.FL = true;  }  else  {    if( _NORMAL::State1==NORMAL.V )      OFFNRMALM.FL = false;    else if( _NORMAL::State0==NORMAL.V )      OFFNRMALM.FL = true;  }}void DIGACQ_IMPL::StepT( SStepCalcParams &dt, LPCSTR pFullName ){  if( PVSRCOPT.ONLYAUTO==PVSRCOPT.V)  {    PVAUTOFL = PVFL = IN;    ZeroMemory( &PVSTSFL, sizeof(PVSTSFL) );    PVSTSFL.NORM = true;  }  else  {    switch( PVSOURCE.V )    {    case PVSOURCE.MAN:      ZeroMemory( &PVSTSFL, sizeof(PVSTSFL) );      PVSTSFL.MAN = true;      break;    case PVSOURCE.SUB:      ZeroMemory( &PVSTSFL, sizeof(PVSTSFL) );      PVSTSFL.UNCERTN = true;      //c PVFL      break;    case PVSOURCE.AUTO:      PVFL = IN;      ZeroMemory( &PVSTSFL, sizeof(PVSTSFL) );      PVSTSFL.NORM = true;      break;    }  }  INVPVFL = !PVFL;  //if( !PVSTSFL.MAN )  {    strcpy_s( PV, STATETEXT[ PVFL ? 1 : 0] );    if( !PVFL )    {      STATE0 = true, STATE1 = false;      if( _NORMAL::State0==NORMAL.V )      {        if( OFFNRMALM.FL && pAlarm )          pAlarm( pFullName, A_OFN, OFFNRMALM.PR, false, 0, &OFFNRMALM.TM, 0, PV );        OFFNRMALM.FL = false;        INALM = false;      }      else if( _NORMAL::State1==NORMAL.V )      {        if( !OFFNRMALM.FL && pAlarm )          pAlarm( pFullName, A_OFN, OFFNRMALM.PR, true, 1, &OFFNRMALM.TM, 0, PV );        OFFNRMALM.FL = true;        INALM = true;      }    }    else    {      STATE0 = false, STATE1 = true;      if( _NORMAL::State1==NORMAL.V )      {        if( OFFNRMALM.FL && pAlarm )          pAlarm( pFullName, A_OFN, OFFNRMALM.PR, false, 1, &OFFNRMALM.TM, 0, PV );        OFFNRMALM.FL = false;        INALM = false;      }      else if( _NORMAL::State0==NORMAL.V )      {        if( !OFFNRMALM.FL && pAlarm )          pAlarm( pFullName, A_OFN, OFFNRMALM.PR, true, 0, &OFFNRMALM.TM, 0, PV );        OFFNRMALM.FL = true;        INALM = true;      }    }  }}